import{_ as l,o as t,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2016-DEC-07 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2016-DEC-07 :: Ceph Performance Weekly","date":"2017-01-11T00:00:00.000Z","updated":"2017-01-12T00:00:00.000Z","tags":["Ceph性能优化","RBD性能测试","ZetaScale存储性能测试","IO路径性能分析","Ceph性能追踪"],"categories":["会议纪要","Ceph","性能测试"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2016-DEC-07_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2016-DEC-07_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2016-DEC-07_-_-_Ceph_Performance_Weekly.md"};function o(_,e,p,s,n,c){return t(),a("div",null,[...e[0]||(e[0]=[i("<p>本次会议主要讨论了Ceph分布式存储系统的性能优化，涵盖了以下关键议题：</p><p><strong>一、关键功能跟踪点分析</strong></p><ul><li>Steve提交了一个PR，用于在IO路径中添加关键功能的跟踪点，以帮助进行性能分析。</li><li>讨论如何改进缓冲区列表以避免不必要的复制。</li><li>Sage和Sam正在测试ZetaScale存储性能，并尝试将其集成到测试套件中。</li></ul><p><strong>二、RBD性能测试</strong></p><ul><li>Steve进行了RVD（RADOS erasure coding）与EC（Erasure Coding）的性能测试，结果显示RVD在大型顺序写操作中表现优异。</li><li>对于小型随机写操作，RVD性能较差，因为需要从主节点获取数据。</li><li>建议开发一个功能，允许客户端直接从各个碎片读取数据，以减少读取操作的延迟。</li></ul><p><strong>三、ZetaScale存储性能测试</strong></p><ul><li>Sage和Sam正在测试ZetaScale存储性能，并尝试将其集成到Ceph中。</li><li>测试了使用单个kv线程的版本和使用多个kv线程的版本。</li><li>预计ZetaScale可以减少RocksDB的压缩开销，并提高大型数据集的性能。</li></ul><p><strong>四、IO路径性能分析</strong></p><ul><li>Say提交了一个PR，用于生成LTTng跟踪点，以跟踪函数级延迟和OID跟踪点，以跟踪操作ID的飞行路径。</li><li>分析结果显示，网络延迟和DQ（dispatch queue）操作是影响性能的关键因素。</li><li>建议优化IO准备、IO队列和线程上下文切换，以减少延迟。</li></ul><p><strong>五、后续行动计划</strong></p><ul><li>继续进行RVD和ZetaScale的性能测试，并优化相关功能。</li><li>分析LTTng跟踪点数据，以识别性能瓶颈。</li><li>优化IO路径，减少延迟。</li><li>在下一个会议上分享更多测试结果。</li></ul>",11)])])}const d=l(r,[["render",o]]);export{C as __pageData,d as default};
